let queue = DispatchQueue(label: "cache", attributes: .concurrent)
func read(_ k: String) -> Data? { queue.sync { storage[k] } }
func write(_ k: String, _ v: Data) {
    queue.async(flags: .barrier) { self.storage[k] = v }
}

let group = DispatchGroup()
for url in urls {
    group.enter()
    api.fetch(url) { result in
        defer { group.leave() }
        results.append(result)   // careful: serialize this!
    }
}
group.notify(queue: .main) { self.reload() }

actor ImageCache {
    private var images: [URL: UIImage] = [:]
    func image(for url: URL) -> UIImage? { images[url] }
    func insert(_ image: UIImage, for url: URL) { images[url] = image }
}

